import{_ as i,a,b as t}from"./chunks/image-16.Ddu1czq-.js";import{_ as n,o,c as l,a2 as s}from"./chunks/framework.CdjpmwdR.js";const f=JSON.parse('{"title":"Cloud‑Native in Practice: From Tools to Engineering Systems","description":"Frames cloud‑native adoption as building an engineering system—standardized capabilities, team responsibilities, and organizational evolution—to turn buzzwords into delivery outcomes.","frontmatter":{"category":"node","date":"2022-11-01","title":"Cloud‑Native in Practice: From Tools to Engineering Systems","description":"Frames cloud‑native adoption as building an engineering system—standardized capabilities, team responsibilities, and organizational evolution—to turn buzzwords into delivery outcomes.","tags":["node","IaC","DevOps"],"image":"/blogs/assets/202211-cloud-native-engineering/image-17.png"},"headers":[],"relativePath":"en/blogs/2022/202211-cloud-native-engineering.md","filePath":"en/blogs/2022/202211-cloud-native-engineering.md"}'),r={name:"en/blogs/2022/202211-cloud-native-engineering.md"};function d(c,e,u,p,g,h){return o(),l("div",null,[...e[0]||(e[0]=[s('<table tabindex="0"><thead><tr><th>Version</th><th>Change</th><th>Time</th></tr></thead><tbody><tr><td>v0.1</td><td>Initial idea</td><td>2022-11</td></tr><tr><td>v0.2</td><td>Outline</td><td>2023-05</td></tr><tr><td>v0.3</td><td>Outline refactor, main chaptering</td><td>2023-08</td></tr><tr><td>v0.4</td><td>Introduction and Chapter 1</td><td>2023-08</td></tr></tbody></table><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>In a market where change keeps accelerating, organizations expect more from software delivery: faster release, more stable operation, and lower cost. A feature‑centric model with platform capabilities patched in afterwards is struggling to keep up.</p><p>Cloud‑native is not just a technology upgrade. Its value lies in putting applications, platforms, processes, and organization into one delivery system.</p><p><img src="'+i+'" alt="Cloud-Native"><img src="'+a+'" alt="Cloud-Native"></p><p>&quot;Cost reduction and efficiency&quot; is one of the main goals of cloud adoption, and a major driver for digital transformation. With cloud computing, DevOps, microservices, and automation, cloud‑native technologies aim to &quot;build <strong>fault‑tolerant</strong>, <strong>manageable</strong>, and <strong>observable</strong> loosely coupled systems that, combined with <strong>automation</strong>, can handle <strong>frequent</strong> and <strong>predictable</strong> changes&quot;.</p><p><img src="'+t+`" alt="Cloud-native architecture"></p><p>But cost reduction does not happen automatically. Loose coupling, elasticity, and automation require developers, ops, and business stakeholders to collaborate toward a shared goal.</p><p>So the focus of cloud‑native adoption is not stacking more tools, but <strong>building an engineering system</strong>: defining standards, clarifying responsibilities, designing processes, and running continuous retrospectives.</p><p>This article focuses on one question: how can enterprises turn &quot;technical concepts&quot; into &quot;engineering results&quot;? We will use a framework based on standardized capabilities, team responsibilities, and organizational evolution.</p><blockquote><p>Disclaimer: this reflects my personal view only. Use it as reference, not as a guaranteed recipe.</p></blockquote><h2 id="chapter-1-cloud‐native-engineering" tabindex="-1">Chapter 1: Cloud‑Native Engineering <a class="header-anchor" href="#chapter-1-cloud‐native-engineering" aria-label="Permalink to &quot;Chapter 1: Cloud‑Native Engineering&quot;">​</a></h2><blockquote><p><strong>Engineering</strong> — applying systematic, repeatable methods to a domain or task under constraints, to achieve a desired outcome.</p></blockquote><h3 id="what-is-engineering" tabindex="-1">What Is Engineering? <a class="header-anchor" href="#what-is-engineering" aria-label="Permalink to &quot;What Is Engineering?&quot;">​</a></h3><p>Engineering is about applying structured, repeatable methods to increase efficiency, quality, and maintainability. It focuses on process, standards, automation, and continuous improvement so that products stay high‑quality across their lifecycle.</p><p>Key ideas include: decomposing complex problems, defining clear steps, using data to support decisions, and iterating via feedback.</p><p>Examples:</p><ul><li>Manufacturing: process optimization, quality control, and cost efficiency.</li><li>Aerospace: design, build, and test under strict safety and reliability constraints.</li><li>Construction: planning, design, construction, and maintenance of buildings and infrastructure.</li><li>Energy and environment: balancing resource usage, sustainability, and regulation.</li><li>Software engineering: building and maintaining large‑scale systems with attention to quality, maintainability, and scalability.</li></ul><p>Scientific innovation often assumes ideal conditions. Without engineering discipline, those assumptions break in real environments:</p><ol><li><strong>Instability and unreliability</strong>: without systematic testing, innovations may be fragile.</li><li><strong>Poor maintainability</strong>: lack of documentation, conventions, and standards makes long‑term evolution hard.</li><li><strong>Weak risk management</strong>: without explicit risk assessment, hidden risks accumulate.</li><li><strong>Project management challenges</strong>: no structure leads to delays, waste, and communication issues.</li><li><strong>Non‑compliance</strong>: many industries require standards and regulation.</li></ol><p>Technology advances productivity, but without engineering methods the result is often unstable, unmaintainable, and risky.</p><h3 id="what-is-cloud‐native-engineering" tabindex="-1">What Is Cloud‑Native Engineering? <a class="header-anchor" href="#what-is-cloud‐native-engineering" aria-label="Permalink to &quot;What Is Cloud‑Native Engineering?&quot;">​</a></h3><p>Cloud‑native tech has exploded in recent years. The CNCF Landscape keeps growing, but many enterprises still struggle with adoption:</p><ul><li>Too many tools, hard to choose.</li><li>Immature technical practices, lacking standardization.</li><li>Team skill gaps, slow onboarding.</li><li>Unclear processes, weak collaboration.</li><li>Technical value hard to articulate, limited business support.</li><li>Costs go up instead of down.</li></ul><p>Most cloud‑native tools solve <strong>specific</strong> problems (orchestration, observability, automation…), but for an enterprise, adoption also involves people, organization, and process.</p><p>There are no silver bullets. To adopt cloud‑native, you must first define the problem space: current pain points, goals, and constraints — then pick technologies and tools to address them, step by step.</p><p><strong>A cloud‑native engineering system</strong> is a structured set of methods and guidelines that drive cloud migration, DevOps, and delivery effectiveness. It spans problem definition, team design, system design, development, testing, and continuous improvement.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>“Review the entire business and remove adjacent activities we cannot serve well;</span></span>
<span class="line"><span>examine complexity end‑to‑end — process, structure, manufacturing, distribution;</span></span>
<span class="line"><span>understand customer needs and set up continuous review.</span></span>
<span class="line"><span>” — Jørgen Vig Knudstorp, LEGO</span></span></code></pre></div><h4 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h4><p>PoV for a cloud‑native engineering system:</p><ul><li>A runbook for cloud‑native adoption.</li><li>Reference paths for organizational evolution: structures, processes, and core capabilities.</li><li>A catalog of key capabilities across tooling, theory, and practice.</li></ul><h4 id="audience" tabindex="-1">Audience <a class="header-anchor" href="#audience" aria-label="Permalink to &quot;Audience&quot;">​</a></h4><ul><li>Tech leaders: team responsibilities, structure, and capability growth.</li><li>Architects: technical choices and architecture design.</li><li>Ops/SRE: platform and reliability capabilities.</li><li>Developers: day‑to‑day engineering practices.</li></ul><h4 id="where-it-applies" tabindex="-1">Where It Applies <a class="header-anchor" href="#where-it-applies" aria-label="Permalink to &quot;Where It Applies&quot;">​</a></h4><ul><li>Cloud migration and cost‑efficiency.</li><li>Reducing cloud‑native complexity.</li><li>Demonstrating platform team value.</li><li>DevOps and delivery effectiveness.</li><li>FinOps and cost management.</li><li>Microservice migration, containerization, observability…</li></ul><h2 id="chapter-2-key-elements-for-cloud‐native-adoption" tabindex="-1">Chapter 2: Key Elements for Cloud‑Native Adoption <a class="header-anchor" href="#chapter-2-key-elements-for-cloud‐native-adoption" aria-label="Permalink to &quot;Chapter 2: Key Elements for Cloud‑Native Adoption&quot;">​</a></h2><p>The only constant is change: technology, business, and organization all evolve. A cloud‑native engineering system must evolve too.</p><ul><li>Different roles and teams see different problems and need different tools.</li><li>At different stages, organizations face different bottlenecks and capacity gaps.</li></ul><blockquote><p>“Complexity seeps into any human organization. New initiatives, new layers of management, new departments, poorly researched products, leveraged financial instruments — all of these add complexity. Complexity grows exponentially, not linearly. Always reduce complexity where you can.” — LEGO, Jørgen Vig Knudstorp</p></blockquote><p>This framework has two views:</p><ul><li><strong>Value stream view</strong>: from delivery perspective, describe problems at a given stage, define roles and their value.</li><li><strong>Evolution view</strong>: from organization perspective, describe transitions between stages and which capabilities are needed.</li></ul><p>Core elements:</p><ul><li><strong>Standardized capabilities</strong><ul><li>Technical and non‑technical.</li><li>Problem‑oriented, implementation‑agnostic; realized via tools.</li></ul></li><li><strong>Responsibilities and team topology</strong><ul><li>Roles and responsibilities.</li><li>Collaboration patterns.</li></ul></li><li><strong>Organizational evolution and culture</strong><ul><li>How industries differ.</li><li>How to transition into cloud‑native teams.</li><li>Culture: agile, DevOps, BizDevOps.</li><li>Growth across small / medium / large / very large organizations.</li></ul></li></ul><h3 id="standardized-capabilities" tabindex="-1">Standardized Capabilities <a class="header-anchor" href="#standardized-capabilities" aria-label="Permalink to &quot;Standardized Capabilities&quot;">​</a></h3><p>Technical capabilities:</p><ul><li>Container orchestration.</li><li>GitOps.</li><li>IaC.</li><li>…</li></ul><p>Non‑technical capabilities:</p><ul><li>Project management.</li><li>Product management.</li><li>People management.</li><li>…</li></ul><p>The goal is a capability model that is concrete and implementable, not abstract buzzwords.</p><h3 id="responsibilities-and-team-organization" tabindex="-1">Responsibilities and Team Organization <a class="header-anchor" href="#responsibilities-and-team-organization" aria-label="Permalink to &quot;Responsibilities and Team Organization&quot;">​</a></h3><p>DevOps team topologies and platform thinking:</p><ul><li><a href="https://www.thoughtworks.com/insights/blog/art-platform-thinking" target="_blank" rel="noreferrer">The Art of Platform Thinking | Thoughtworks</a></li></ul><p>Platform engineering:</p><ul><li>Atlassian: platform teams create capabilities consumed by product teams, reducing their cognitive load.</li><li>Fowler/Bottcher: a digital platform is a self‑service base of APIs, tools, services, and knowledge. Autonomous delivery teams build on top of it.</li><li>CNCF TAG App Delivery: <a href="https://tag-app-delivery.cncf.io/whitepapers/platforms/" target="_blank" rel="noreferrer">Platforms whitepaper</a></li></ul><p>Topics:</p><ul><li>Redefining roles and orgs <ul><li>CloudOps, DevOps, SRE.</li><li>Product vs project vs shared platforms.</li></ul></li><li>Evolution directions <ul><li>From ad‑hoc ops to SRE.</li><li>From project teams to long‑lived product teams.</li></ul></li></ul><p>Examples of standardized responsibilities:</p><ul><li>Define technical standards and best practices.</li><li>Unified container image management.</li><li>Infrastructure as Code baselines.</li></ul><h3 id="organizational-evolution-and-culture" tabindex="-1">Organizational Evolution and Culture <a class="header-anchor" href="#organizational-evolution-and-culture" aria-label="Permalink to &quot;Organizational Evolution and Culture&quot;">​</a></h3><p>Standardized capabilities are building blocks. Org structure is the blueprint that assigns these capabilities. Process is the connective tissue that activates the org toward a goal.</p><p>When an organization adopts a set of capabilities for a clear objective, that is engineering.</p><ul><li>Dev (feature teams) – DevOps (enabling teams) – SRE (platform team) – Ops (cloud platform).</li></ul><p>Evolution examples (simplified):</p><ul><li>Small teams <ul><li>DevOps as external service; operations partially outsourced.</li></ul></li><li>Medium teams <ul><li>DevOps advocacy team appears; Dev and Ops concerns increase.</li></ul></li><li>Large teams <ul><li>Dedicated SRE team; platform standards and toolchains; DevOps builds on SRE‑provided products.</li></ul></li></ul><p>Mapping (one possible view):</p><ul><li>SRE ≈ CloudOps, DevOps ≈ platform engineering, Ops ≈ infra/cloud providers.</li></ul><p>Key questions per stage:</p><ul><li>Where are we now? What capabilities do we have?</li><li>What is the next stage? What problems will appear?</li><li>Which capabilities close those gaps?</li></ul><h2 id="chapter-3-evolution-paths-and-case-studies" tabindex="-1">Chapter 3: Evolution Paths and Case Studies <a class="header-anchor" href="#chapter-3-evolution-paths-and-case-studies" aria-label="Permalink to &quot;Chapter 3: Evolution Paths and Case Studies&quot;">​</a></h2><p>Using the elements above, we can analyze concrete organizations.</p><ul><li>By organization size as a rough axis: <ul><li>10–25–50–99: small / mid‑size teams.</li><li>100–150–250: larger teams.</li><li>299+: very large orgs.</li></ul></li><li>For each, consider: <ul><li>Goals, direction, and main pain points.</li><li>People and capabilities.</li></ul></li></ul><h3 id="value-realization" tabindex="-1">Value Realization <a class="header-anchor" href="#value-realization" aria-label="Permalink to &quot;Value Realization&quot;">​</a></h3><p>Questions organizations keep asking:</p><ul><li>Why move to cloud? Why move off cloud?</li><li>How should the internal platform team evolve?</li><li>What if the platform team does not own infra but only wraps interfaces?</li><li>When incidents happen, how do we avoid blame ping‑pong between platform and infra?</li><li>How do we gather and prioritize business requirements for the platform?</li></ul><p>These are all value questions. Different orgs and stages have different value stories.</p><p>With the capability × organization view we can:</p><ul><li><strong>Analyze</strong> current stage and capabilities, and likely next stage.</li><li><strong>Design</strong> org changes, capability building, and tool choices.</li><li><strong>Plan</strong> timelines, stakeholders, and investment.</li><li><strong>Implement</strong> as iterative evolution with feedback.</li><li><strong>Summarize</strong> experience into practices that can travel.</li></ul><h3 id="example-enterprise-x-s-cloud‐native-journey" tabindex="-1">Example: Enterprise X’s Cloud‑Native Journey <a class="header-anchor" href="#example-enterprise-x-s-cloud‐native-journey" aria-label="Permalink to &quot;Example: Enterprise X’s Cloud‑Native Journey&quot;">​</a></h3><p>(Placeholder for a concrete case: background and challenges, chosen technologies and strategies, lessons and outcomes.)</p><h3 id="success-factors" tabindex="-1">Success Factors <a class="header-anchor" href="#success-factors" aria-label="Permalink to &quot;Success Factors&quot;">​</a></h3><p>At the end, we can extract a set of success patterns and how to apply them at different stages and in different org shapes.</p><h2 id="closing-the-next-station-for-cloud‐native" tabindex="-1">Closing: The Next Station for Cloud‑Native <a class="header-anchor" href="#closing-the-next-station-for-cloud‐native" aria-label="Permalink to &quot;Closing: The Next Station for Cloud‑Native&quot;">​</a></h2><h3 id="future-directions" tabindex="-1">Future Directions <a class="header-anchor" href="#future-directions" aria-label="Permalink to &quot;Future Directions&quot;">​</a></h3><ul><li>Emerging technologies and patterns.</li><li>Skills cloud‑native practitioners will need.</li></ul><h3 id="suggestions-looking-forward" tabindex="-1">Suggestions Looking Forward <a class="header-anchor" href="#suggestions-looking-forward" aria-label="Permalink to &quot;Suggestions Looking Forward&quot;">​</a></h3><ul><li>How to sustain cloud‑native adoption, not treat it as a one‑off project.</li><li>How to grow people and enable knowledge sharing.</li></ul><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><ul><li>ChatGPT</li><li><a href="https://martinfowler.com/articles/talk-about-platforms.html" target="_blank" rel="noreferrer">https://martinfowler.com/articles/talk-about-platforms.html</a></li><li><a href="https://www.zhihu.com/question/24292554" target="_blank" rel="noreferrer">https://www.zhihu.com/question/24292554</a></li><li><a href="https://mp.weixin.qq.com/s/sRRqJS8dOrtbTrnef16eUQ" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/sRRqJS8dOrtbTrnef16eUQ</a></li></ul>`,89)])])}const v=n(r,[["render",d]]);export{f as __pageData,v as default};
